'use client'

import { useEffect, useState } from 'react'
import { CryptoAsset, CryptoResponse } from '@/types/cryptoAsset'
import CryptoCard from '@/components/CryptoCard'
import Pagination from '@/components/Pagination'
import axios from 'axios'
import { log } from 'console'

const PAGE_SIZE = 12

export default function DashboardPage() {
  const [assets, setAssets] = useState<CryptoAsset[]>([])
  const [currentPage, setCurrentPage] = useState(1)

  useEffect(() => {
    async function fetchAssets() {
      try {
        const res = await axios.get<CryptoResponse>('https://data.messari.io/api/v1/assets')
        log(res.data.data)
        setAssets(res.data.data)
      } catch (error) {
        console.error('❌ Failed to fetch crypto assets:', error)
      }
    }
    fetchAssets()
  }, [])

  const start = (currentPage - 1) * PAGE_SIZE
  const currentAssets = assets.slice(start, start + PAGE_SIZE)

  return (
    <main className="max-w-7xl mx-auto px-6 py-10">
      <h1 className="text-3xl font-bold text-white mb-8">📈 Market Overview</h1>
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
        {currentAssets.map(asset => (
          <CryptoCard key={asset.id} asset={asset} />
        ))}
      </div>
      <Pagination
        currentPage={currentPage}
        totalPages={Math.ceil(assets.length / PAGE_SIZE)}
        onPageChange={setCurrentPage}
      />
    </main>
  )
}
