'use client'
import { CryptoAsset } from "@/types/crypto" 

export default function CryptoCard({ asset }: { asset: CryptoAsset }) {
  const price = asset.metrics.market_data.price_usd.toFixed(2)
  const change = asset.metrics.market_data.percent_change_usd_last_24_hours.toFixed(2)
  const marketCap = asset.market_cap.market_cap_usd.toLocaleString('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0
  })

  return (
    <div className="bg-gray-800 p-4 rounded-lg shadow-md border border-gray-700 hover:border-yellow-400 transition">
      <div className="flex justify-between items-center mb-2">
        <h2 className="text-lg font-bold text-yellow-400">
          {asset.name} ({asset.symbol})
        </h2>
      </div>
      <p className="text-white text-xl">${price}</p>
      <p className={`text-sm ${change.startsWith('-') ? 'text-red-500' : 'text-green-400'}`}>
        {change}% (24h)
      </p>
      <p className="text-sm text-gray-400 mt-2">Market Cap: {marketCap}</p>
    </div>
  )
}
